const $=(s,p=document)=>p.querySelector(s);const $$=(s,p=document)=>[...p.querySelectorAll(s)];
const menu=$('.menu-toggle'),nav=$('#main-nav');
menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',open);nav.classList.toggle('open',open)});
$('.drop-toggle')?.addEventListener('click',e=>{const open=e.currentTarget.getAttribute('aria-expanded')!=='true';e.currentTarget.setAttribute('aria-expanded',open);$('.nav-service').classList.toggle('open',open)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){nav?.classList.remove('open');menu?.setAttribute('aria-expanded','false');$('.nav-service')?.classList.remove('open');$('.drop-toggle')?.setAttribute('aria-expanded','false')}});
const mobile=$('.mobile-cta'),hero=$('#hero')||$('.page-hero')||$('.contact-section');
if(hero&&'IntersectionObserver' in window)new IntersectionObserver(entries=>{for(const e of entries)mobile?.classList.toggle('visible',!e.isIntersecting&&e.boundingClientRect.bottom<0)},{threshold:0}).observe(hero);
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
if(document.body.dataset.page==='home'){
 const video=$('#cinematic-video'),controls=$('.intro-controls'),replay=$('#replay-intro'),content=$('.hero-content'),sound=$('#intro-sound');
 let playing=false,loadTimer,hardTimer;replay.hidden=false;
 const done=()=>{clearTimeout(loadTimer);clearTimeout(hardTimer);playing=false;video.pause();video.classList.remove('active');document.body.classList.remove('intro-playing','intro-reveal');content.inert=false;controls.hidden=true;replay.hidden=false;try{sessionStorage.setItem('es-intro-v2','1')}catch{}if(controls.contains(document.activeElement))replay.focus({preventScroll:true})};
 const start=async()=>{if(playing)return;playing=true;replay.hidden=true;video.muted=true;sound.textContent='Sound Off';sound.setAttribute('aria-pressed','false');video.src=matchMedia('(max-width:600px)').matches?'/assets/cinematic-mobile.mp4':'/assets/cinematic-desktop.mp4';loadTimer=setTimeout(done,2000);hardTimer=setTimeout(done,13000);try{await video.play()}catch{done()}};
 video.addEventListener('playing',()=>{if(!playing)return;clearTimeout(loadTimer);video.classList.add('active');document.body.classList.add('intro-playing');content.inert=true;controls.hidden=false});
 video.addEventListener('timeupdate',()=>{if(playing&&video.currentTime>video.duration*.57){document.body.classList.add('intro-reveal');content.inert=false}});
 video.addEventListener('ended',done);video.addEventListener('error',done);
 $('#skip-intro').addEventListener('click',done);replay.addEventListener('click',start);
 sound.addEventListener('click',()=>{video.muted=!video.muted;sound.textContent=video.muted?'Sound Off':'Sound On';sound.setAttribute('aria-pressed',String(!video.muted))});
 document.addEventListener('visibilitychange',()=>{if(!playing)return;if(document.hidden)video.pause();else video.play().catch(done)});
 if('IntersectionObserver'in window)new IntersectionObserver(es=>{if(playing&&!es[0].isIntersecting)done()},{threshold:0}).observe($('#hero'));
 reduced.addEventListener('change',()=>{if(reduced.matches&&playing)done()});
 let seen=false;try{seen=sessionStorage.getItem('es-intro-v2')==='1'}catch{}
 if(!seen&&!reduced.matches&&!navigator.connection?.saveData)start();
}
if(matchMedia('(hover:hover) and (pointer:fine)').matches&&!reduced.matches){const cursor=$('#cursor');let frame=0;document.addEventListener('pointermove',e=>{if(frame)return;frame=requestAnimationFrame(()=>{cursor.style.left=e.clientX+'px';cursor.style.top=e.clientY+'px';document.body.classList.add('cursor-visible');frame=0})});document.addEventListener('pointerleave',()=>document.body.classList.remove('cursor-visible'))}
$$('[data-filter]').forEach(b=>b.addEventListener('click',()=>{$$('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$$('.project-card').forEach(p=>p.hidden=b.dataset.filter!=='All'&&p.dataset.category!==b.dataset.filter)}));
if($('#area-map'))fetch('/areas.json').then(r=>{if(!r.ok)throw new Error();return r.json()}).then(cities=>{$$('[data-city]').forEach(b=>b.addEventListener('click',()=>{const c=cities[Number(b.dataset.city)];$$('[data-city]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b))});$('#area-region').textContent=c.region;$('#area-name').textContent=c.name;$('#area-copy').textContent=c.text;$('#area-map').src=`https://www.openstreetmap.org/export/embed.html?bbox=${c.lng-.12}%2C${c.lat-.09}%2C${c.lng+.12}%2C${c.lat+.09}&layer=mapnik`;const l=$('#area-link');l.href=Number(b.dataset.city)<2?'/service-areas/'+c.name.toLowerCase().replaceAll(' ','-')+'/':'/contact/?city='+encodeURIComponent(c.name);l.textContent=Number(b.dataset.city)<2?'Explore '+c.name+' plumbing':'Confirm coverage in '+c.name}))}).catch(()=>{});
$$('.view-image').forEach(b=>b.addEventListener('click',()=>{const d=document.createElement('dialog');d.className='lightbox';const close=document.createElement('button');close.textContent='Close image';const im=document.createElement('img');im.src=b.dataset.image;im.alt='Illustrative stock plumbing photograph, not an E&S project';const p=document.createElement('p');p.textContent='Illustrative stock photography. Not a photograph of this E&S project.';d.append(close,im,p);document.body.append(d);close.addEventListener('click',()=>d.close());d.addEventListener('close',()=>d.remove());d.addEventListener('click',e=>{if(e.target===d)d.close()});d.showModal()}));
const form=$('#estimate-form');
if(form){let step=0;const values={service:'',property:'',city:new URLSearchParams(location.search).get('city')||'',details:'',name:'',phone:'',email:'',method:'Text'};const root=$('#form-step'),err=$('#form-error'),next=$('#form-next'),back=$('#form-back');const escape=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
const choices=(name,options)=>'<div class="choice-list">'+options.map((o,i)=>`<label class="choice"><input type="radio" name="${name}" value="${escape(o)}" ${values[name]===o?'checked':''} ${i===0?'required':''}><span>${escape(o)}</span></label>`).join('')+'</div>';
const field=(title,name,type='text',required=false)=>`<label class="field">${title}<input name="${name}" type="${type}" value="${escape(values[name])}" ${required?'required':''} ${name==='name'?'autocomplete="name"':name==='phone'?'autocomplete="tel"':name==='email'?'autocomplete="email"':''}></label>`;
const capture=()=>{new FormData(form).forEach((v,k)=>{if(k in values)values[k]=String(v).trim()})};
const render=()=>{err.textContent='';$('#step-count').textContent=`STEP ${step+1} OF 6`;$('#progress-fill').style.width=((step+1)/6*100)+'%';back.hidden=step===0;next.hidden=step===5;const titles=['What do you need help with?','What kind of property?','Where is the project?','Tell us a little more.','How can we reach you?','Review your request.'];let body='';if(step===0)body=choices('service',['Drain or Sewer','Water Heater','Leak or Repair','ADU or New Construction','Commercial Plumbing','Other Plumbing Work']);if(step===1)body=choices('property',['Residential','Commercial','New Construction / ADU']);if(step===2)body=field('City or ZIP code','city','text',true)+'<p class="small" style="color:#536b76">We’ll confirm coverage for the specific project address.</p>';if(step===3)body=`<label class="field">A short description (optional)<textarea name="details" maxlength="1500">${escape(values.details)}</textarea></label>`;if(step===4)body=field('Your name','name','text',true)+field('Phone number','phone','tel',true)+field('Email (optional)','email','email')+`<label class="field">Preferred reply method<select name="method">${['Text','Call'].map(x=>`<option ${values.method===x?'selected':''}>${x}</option>`).join('')}</select></label>`;if(step===5)body=`<dl class="summary-table">${[['Service',values.service],['Property',values.property],['Location',values.city],['Details',values.details||'Not added'],['Name',values.name],['Phone',values.phone],['Email',values.email||'Not added'],['Reply by',values.method]].map(([k,v])=>`<dt>${k}</dt><dd>${escape(v)}</dd>`).join('')}</dl><p class="review-notice">Your request has not been sent. Open your messaging app below, review the text, and send it to E&amp;S. For a confirmed appointment, wait for a reply or call the team.</p><a id="send-text" class="button dark" href="#">Open Text Message</a><p class="small" style="color:#536b76;margin-top:15px">On a computer without text messaging, copy your details and call (619) 507-4947.</p><button class="text-link" type="button" id="copy-details">Copy request details</button><p id="copy-status" aria-live="polite"></p>`;root.innerHTML=`<h2 tabindex="-1">${titles[step]}</h2>`+body;if(step===5){const message=`Free estimate request\nService: ${values.service}\nProperty: ${values.property}\nLocation: ${values.city}\nDetails: ${values.details||'Not provided'}\nName: ${values.name}\nPhone: ${values.phone}\nEmail: ${values.email||'Not provided'}\nPreferred reply: ${values.method}`;$('#send-text').href='sms:+16195074947?body='+encodeURIComponent(message);$('#copy-details').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(message);$('#copy-status').textContent='Copied. Your request has not been sent.'}catch{$('#copy-status').textContent='Copy is unavailable in this browser. Select and copy the details above.'}})}if(step===5)configureEstimateEndpoint(root,values);return root.querySelector('h2')};
next.addEventListener('click',()=>{capture();if(!form.reportValidity())return;if(step===0&&!values.service||step===1&&!values.property){err.textContent='Please choose an option to continue.';return}if(step===2&&values.city.length<2){err.textContent='Enter a city or ZIP code.';return}if(step===4&&values.phone.replace(/\D/g,'').length<10){err.textContent='Enter a phone number with at least 10 digits.';return}step=Math.min(5,step+1);render().focus()});back.addEventListener('click',()=>{capture();step=Math.max(0,step-1);render().focus()});form.addEventListener('submit',e=>e.preventDefault());render();}

function configureEstimateEndpoint(root,values){
 const endpoint=window.ES_SITE_CONFIG?.estimateEndpoint;if(!endpoint)return;
 let target;try{target=new URL(endpoint,location.origin);if(target.protocol!=='https:'&&target.origin!==location.origin)return}catch{return}
 const button=document.createElement('button');button.type='button';button.className='button primary form-submit';button.textContent='Submit Free-Estimate Request';
 const status=document.createElement('p');status.setAttribute('role','status');status.className='review-notice';status.textContent='Submit your details securely, or use the text-message option above.';root.append(button,status);
 button.addEventListener('click',async()=>{button.disabled=true;status.textContent='Sending your request…';const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),12000);try{const response=await fetch(target.href,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...values,website:''}),signal:controller.signal});let result;try{result=await response.json()}catch{}if(!response.ok||result?.success!==true)throw new Error();status.textContent='Your request was received. The team will confirm availability and next steps directly. This does not book an appointment.';button.textContent='Request Received';}catch{status.textContent='Your request could not be confirmed. Please call or use the text-message option. Your details are still here.';button.disabled=false;}finally{clearTimeout(timer)}});
}
